SelectSeparator.displayName = SelectPrimitive.Separator.displayName;

// Wrapper component that accepts onChange (for backwards compatibility)
// This is a simple wrapper that manages its own state
interface SelectWrapperProps {
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  children: React.ReactNode;
  className?: string;
}

// We need to use a different approach - create a component that wraps the Select primitive
// but handles onChange by managing internal state
function SelectWrapper({
  value,
  defaultValue,
  onChange,
  children,
  className,
}: SelectWrapperProps) {
  const [internalValue, setInternalValue] = React.useState(defaultValue || "");
  const controlled = value !== undefined;
  const currentValue = controlled ? value : internalValue;

  const handleValueChange = (newValue: string) => {
    if (!controlled) setInternalValue(newValue);
    onChange?.(newValue);
  };

  return (
    <SelectPrimitive.Root
      value={currentValue}
      onValueChange={handleValueChange}
    >
      {children}
    </SelectPrimitive.Root>
  );
}

export {
  SelectWrapper as Select,
  SelectGroup,
  SelectValue,
  SelectTrigger,
  SelectContent,
  SelectLabel,
  SelectItem,
  SelectSeparator,
  SelectScrollUpButton,
  SelectScrollDownButton,
};